// ExecutorServiceHandler is an implementation of the lindm.agent.v1.ExecutorService service.
type ExecutorServiceHandler interface {
	// PrepareBootstrap validates supplied trust, or returns the existing pending
	// attempt. Root only. The response may include the pending grant and never
	// includes a private key. resume never generates another identity.
	PrepareBootstrap(context.Context, *connect.Request[v1.PrepareBootstrapRequest]) (*connect.Response[v1.PrepareBootstrapResponse], error)
	// InstallEnrollment verifies the server certificate against the protected
	// pending key and deployment, then commits and removes the grant before
	// acknowledgment. Root only.
	InstallEnrollment(context.Context, *connect.Request[v1.InstallEnrollmentRequest]) (*connect.Response[v1.InstallEnrollmentResponse], error)
	// Root-only signed offline response import; rejects already installed attempts.
	ImportOfflineEnrollment(context.Context, *connect.Request[v1.ImportOfflineEnrollmentRequest]) (*connect.Response[v1.ImportOfflineEnrollmentResponse], error)
	// GetConnection returns public connection material. An expired active
	// certificate is not a TLS credential. Pending retrieval public data is
	// still returned. session_epoch is usable only after CommitSession and
	// while no renewal is pending.
	GetConnection(context.Context, *connect.Request[v1.GetConnectionRequest]) (*connect.Response[v1.GetConnectionResponse], error)
	// SignTLSClientMessage signs one complete TLS 1.3 client CertificateVerify
	// message for the current certificate or the bounded prior certificate.
	// It is not a digest, renewal, or payload oracle.
	SignTLSClientMessage(context.Context, *connect.Request[v1.SignTLSClientMessageRequest]) (*connect.Response[v1.SignTLSClientMessageResponse], error)
	// PrepareSession returns the committed epoch for this boot, or the exact
	// persisted acquisition proof. It refuses while a renewal is unresolved.
	PrepareSession(context.Context, *connect.Request[v1.PrepareSessionRequest]) (*connect.Response[v1.PrepareSessionResponse], error)
	// CommitSession accepts only the protected pending request UUID and
	// predecessor+1. The exact acknowledgment retry is idempotent. It refuses
	// while a renewal is unresolved.
	CommitSession(context.Context, *connect.Request[v1.CommitSessionRequest]) (*connect.Response[v1.CommitSessionResponse], error)
	// PrepareRenewal returns the executor-generated CSR and proofs. An existing
	// pending intent is returned unchanged, including when the old certificate
	// can no longer authenticate. It does not renew before the stored time.
	PrepareRenewal(context.Context, *connect.Request[v1.PrepareRenewalRequest]) (*connect.Response[v1.PrepareRenewalResponse], error)
	// CommitRenewal installs a certificate that matches the pending next key
	// and pinned identity before acknowledgment.
	CommitRenewal(context.Context, *connect.Request[v1.CommitRenewalRequest]) (*connect.Response[v1.CommitRenewalResponse], error)
	// PrepareEncryptionKey returns the identity-signed attestation of the current
	// HPKE recipient key, generating the key once for pre-delivery journals. The
	// private key is never returned.
	PrepareEncryptionKey(context.Context, *connect.Request[v1.PrepareEncryptionKeyRequest]) (*connect.Response[v1.PrepareEncryptionKeyResponse], error)
	// AcknowledgeEncryptionKey records that the server registered the exact key
	// under the exact current certificate. It is only a re-registration hint.
	AcknowledgeEncryptionKey(context.Context, *connect.Request[v1.AcknowledgeEncryptionKeyRequest]) (*connect.Response[v1.AcknowledgeEncryptionKeyResponse], error)
	// UpdateExecutionTrust verifies both rotation quorums and root-signed online
	// delegation, then durably commits rollback fences before acknowledgment.
	// This never starts work or accepts caller-selected verification keys.
	UpdateExecutionTrust(context.Context, *connect.Request[v1.UpdateExecutionTrustRequest]) (*connect.Response[v1.UpdateExecutionTrustResponse], error)
	// Reads protected public trust facts, not fresh resource observations.
	GetExecutionTrust(context.Context, *connect.Request[v1.GetExecutionTrustRequest]) (*connect.Response[v1.GetExecutionTrustResponse], error)
	// Reads native recovery capability and ESP capacity without changing boot state.
	GetRecoveryReadiness(context.Context, *connect.Request[v1.GetRecoveryReadinessRequest]) (*connect.Response[v1.GetRecoveryReadinessResponse], error)
	// Reads the last offline patch status; a stale status starts the static
	// lindm-os-update-status.service refresh without waiting for it.
	GetPatchStatus(context.Context, *connect.Request[v1.GetPatchStatusRequest]) (*connect.Response[v1.GetPatchStatusResponse], error)
	// Reads the root-local approved home roots and package sources that profiles
	// reference, for publication with host inventory. Changes nothing.
	GetApprovedConfiguration(context.Context, *connect.Request[v1.GetApprovedConfigurationRequest]) (*connect.Response[v1.GetApprovedConfigurationResponse], error)
	// Verifies and journals intent before native preparation. Package staging is
	// asynchronous; exact retries poll without extending its signed deadline.
	PrepareResourceExecution(context.Context, *connect.Request[v1.PrepareResourceExecutionRequest]) (*connect.Response[v1.PrepareResourceExecutionResponse], error)
	// Accepts a separately signed start grant. Native work runs durably outside
	// the RPC; acceptance is not completion. Exact retries never repeat effects.
	StartResourceExecution(context.Context, *connect.Request[v1.StartResourceExecutionRequest]) (*connect.Response[v1.StartResourceExecutionResponse], error)
	// Returns durable action state/evidence, not fresh compliance or authority.
	GetResourceExecution(context.Context, *connect.Request[v1.GetResourceExecutionRequest]) (*connect.Response[v1.GetResourceExecutionResponse], error)
	// Cancels only exact ungranted preparation, never queued or consumed effects.
	CancelResourcePreparation(context.Context, *connect.Request[v1.CancelResourcePreparationRequest]) (*connect.Response[v1.CancelResourcePreparationResponse], error)
	// Signs a nonce-bound snapshot of protected action history using the current
	// device identity/session. Does not observe native state or authorize effects.
	AttestResourceExecution(context.Context, *connect.Request[v1.AttestResourceExecutionRequest]) (*connect.Response[v1.AttestResourceExecutionResponse], error)
	PrepareDeviceAction(context.Context, *connect.Request[v1.PrepareDeviceActionRequest]) (*connect.Response[v1.PrepareDeviceActionResponse], error)
	StartDeviceAction(context.Context, *connect.Request[v1.StartDeviceActionRequest]) (*connect.Response[v1.StartDeviceActionResponse], error)
	GetDeviceAction(context.Context, *connect.Request[v1.GetDeviceActionRequest]) (*connect.Response[v1.GetDeviceActionResponse], error)
	AttestDeviceAction(context.Context, *connect.Request[v1.AttestDeviceActionRequest]) (*connect.Response[v1.AttestDeviceActionResponse], error)
	ConfirmDeviceActionEscrow(context.Context, *connect.Request[v1.ConfirmDeviceActionEscrowRequest]) (*connect.Response[v1.ConfirmDeviceActionEscrowResponse], error)
	ConfirmDeviceActionInventory(context.Context, *connect.Request[v1.ConfirmDeviceActionInventoryRequest]) (*connect.Response[v1.ConfirmDeviceActionInventoryResponse], error)
	PrepareDeviceActionRecovery(context.Context, *connect.Request[v1.PrepareDeviceActionRecoveryRequest]) (*connect.Response[v1.PrepareDeviceActionRecoveryResponse], error)
	CommitDeviceActionRecovery(context.Context, *connect.Request[v1.CommitDeviceActionRecoveryRequest]) (*connect.Response[v1.CommitDeviceActionRecoveryResponse], error)
	// Root-only one-use owner credential; never persisted or returned.
	SupplyDeviceActionCredential(context.Context, *connect.Request[v1.SupplyDeviceActionCredentialRequest]) (*connect.Response[v1.SupplyDeviceActionCredentialResponse], error)
	// Bounded untrusted transport answers to executor-selected TUF fetches.
	ExchangeAgentUpdate(context.Context, *connect.Request[v1.ExchangeAgentUpdateRequest]) (*connect.Response[v1.ExchangeAgentUpdateResponse], error)
	GetAgentUpdate(context.Context, *connect.Request[v1.GetAgentUpdateRequest]) (*connect.Response[v1.GetAgentUpdateResponse], error)
	// Status reports durable lifecycle facts. It does not report transport
	// reachability or any secret, grant, private key, or signed envelope.
	Status(context.Context, *connect.Request[v1.StatusRequest]) (*connect.Response[v1.StatusResponse], error)
	// SyncAssistance applies the server's complete assistance directives and
	// returns the device-observed state. Local identities come from logind and
	// kernel peer credentials, not from a session helper.
	SyncAssistance(context.Context, *connect.Request[v1.SyncAssistanceRequest]) (*connect.Response[v1.SyncAssistanceResponse], error)
}

